}
ops={'>':lambda x,y:x>y,'>=':lambda x,y:x>=y}
fees={'ok':lambda B,w,a:fee(a),'ge':lambda B,w,a:5 if a>=100 else 0,'w':lambda B,w,a:5 if w+a>100 else 0,'B':lambda B,w,a:5 if B>100 else 0, 'Ba':lambda B,w,a:5 if B-a>100 else 0,'wa2':lambda B,w,a:5 if w>100 or a>100 else 0}
conds=[(l,o,r) for l in terms for o in ops for r in terms if l!=r]
res=[]
# mutate funds check (keeps fee in result) or DL check
for (l,o,r) in conds:
    L,O,R=terms[l],ops[o],terms[r]
    for which in ('DL','F'):
        for fn,fe in fees.items():
            def g(B,w,a):
                f=fe(B,w,a)
                if which=='DL':
                    if O(L(B,w,a,f),R(B,w,a,f)): return 'D'
                    if a+f>B: return 'F'
                else:
                    if w+a>200: return 'D'
                    if O(L(B,w,a,f),R(B,w,a,f)): return 'F'
                return 'ok'
            # fee in result only matters on success: compare (status, fee if ok)
            def full(B,w,a):
                s=g(B,w,a); return (s, fe(B,w,a) if s=='ok' else 0)
            def rf(B,w,a):
                s=ref(B,w,a); return (s, fee(a) if s=='ok' else 0)
            tst=sum(full(B,w,a)!=rf(B,w,a) for B in TB for w in TW for a in AM)
            if tst: continue
            dom=sum(full(B,w,a)!=rf(B,w,a) for B in DB for w in DW for a in AM)
            if dom: res.append((dom,which,fn,l,o,r))
for x in sorted(res): print(x)
